func (e *Engine) readLabel(reference objectRef) (int64, error) {
	object, err := e.arena.resolveObject(reference)
	if err != nil {
		return 0, err
	}
	if e.singletonArm.object != 0 {
		if object.present && object.environment != 0 && e.singletonArm.object == reference && e.singletonArm.environment == object.environment {
			cell, err := e.arena.environmentCell(e.singletonArm.environment)
			if err != nil {
				return 0, err
			}
			cell++
			if err = e.arena.storeEnvironmentCell(e.singletonArm.environment, cell); err != nil {
				return 0, err
			}
			return cell, nil
		}
	}
	if e.ordinaryArm.valid {
		if !object.present && object.environment == 0 && object.dispatch == e.ordinaryArm.dispatch && object.shape == e.ordinaryArm.shape {
			e.ordinaryArm.hits++
			return e.ordinaryArm.value, nil
		}
		e.ordinaryArm.misses++
	}
	if !object.present {
		if object.environment != 0 {
			return 0, errInvalidRef
		}
		e.ordinaryArm.dispatch = object.dispatch
		e.ordinaryArm.shape = object.shape
		e.ordinaryArm.value = 7
		e.ordinaryArm.valid = true
		return e.ordinaryArm.value, nil
	}
	if object.environment == 0 {
		return 0, errInvalidRef
	}
	if e.singletonArm.object != reference || e.singletonArm.environment != object.environment {
		if _, err = e.arena.resolveEnvironment(object.environment); err != nil {
			return 0, err
		}
		e.singletonArm = weakArm{object: reference, environment: object.environment}
	}
	cell, err := e.arena.environmentCell(e.singletonArm.environment)
	if err != nil {
		return 0, err
	}
	cell++
	if err = e.arena.storeEnvironmentCell(e.singletonArm.environment, cell); err != nil {
		return 0, err
	}
	return cell, nil
}

func (e *Engine) primeEnvironmentPressure() error {
	for i := 0; i < environmentCapacity; i++ {
		if _, err := e.arena.allocateObject(); err != nil {
			return err
		}
		reference, err := e.arena.reserveEnvironment(integerValue(int64(i)))
		if err != nil {
			return err
		}
		index, generation, ok := unpack(uint32(reference))
		if !ok || int(index) > len(e.arena.environments) {
			return errInvalidRef
		}
		slot := &e.arena.environments[index-1]
		if !slot.reserved || slot.live || slot.generation != generation {
			return errInvalidRef
		}
		slot.reserved = false
		slot.live = true
		e.arena.stats.EnvironmentAllocations++
		e.arena.stats.LiveEnvironments++
	}
	if e.arena.objectFree != uint8(environmentCapacity+1) || e.arena.environmentFree != 0 {
		return errInvalidRef
	}
	return nil
}

// probeEnvironmentPressure is a product-local proof hook. It runs the exact
// product with unreachable pressure records so environment allocation must
// collect while the receiver exists only in install_h1b's object root.
func (e *Engine) probeEnvironmentPressure(ctx context.Context) error {
	if e == nil || e.closed {
		return ErrClosed
	}
	if e.busy {
		return ErrBusy
	}
	e.forceEnvironmentPressure = true
	_, err := e.Run(ctx, ProofLimits())
	e.forceEnvironmentPressure = false
	return err
}

func (e *Engine) Close() error {
	if e == nil || e.closed {
		return nil
	}
	if e.busy {
		return ErrBusy
	}
	e.arena = arena{}
	e.ordinaryArm = ordinaryPICArm{}
	e.singletonArm = weakArm{}
	e.forceEnvironmentPressure = false
	e.poisoned = false
	e.closed = true
	return nil
}
